enum Dir { Up, Down, Left, Right }

fn dir_of(k: i32) -> Dir {
    if k == 0 { Dir::Right } else { if k == 1 { Dir::Down } else { if k == 2 { Dir::Left } else { Dir::Up } } }
}

fn dir_dx(d: Dir) -> i32 {
    match d {
        Dir::Left => -2,
        Dir::Right => 2,
        _ => 0,
    }
}

fn dir_dy(d: Dir) -> i32 {
    match d {
        Dir::Up => -2,
        Dir::Down => 2,
        _ => 0,
    }
}

fn frame(t: i32) {
    let leg: i32 = (t / 40) % 4;
    let step: i32 = t % 40;
    let d: Dir = dir_of(leg);
    let mut x: i32 = 60;
    let mut y: i32 = 60;
    if leg == 1 { x = 140; }
    if leg == 2 { x = 140; y = 140; }
    if leg == 3 { y = 140; }
    x = x + dir_dx(d) * step;
    y = y + dir_dy(d) * step;
    host::display::clear(0x000000);
    host::display::fill_rect(x, y, 20, 20, 0xffcc00);
    host::display::present();
}
